// Copies code the web app must share byte for byte with the backend, so both always agree:
//  - the typed ABIs generated by the backend (from the audited contract build);
//  - the anchor commitment (contract-spec 7.1) from @pt/anchor, which the public verification page
//    recomputes in the browser (S-07 PV-21).
// Run after `npm run gen:abis` in backend/ or after any change to the anchor commitment. CI checks
// that both copies are identical (`cmp`).
import { copyFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const copies = [
  ["../../backend/packages/contracts/src/abis.ts", "../src/lib/abis.ts"],
  ["../../backend/packages/anchor/src/commitment.ts", "../src/lib/anchor-commitment.ts"],
];
for (const [src, dst] of copies) {
  const from = fileURLToPath(new URL(src, import.meta.url));
  const to = fileURLToPath(new URL(dst, import.meta.url));
  copyFileSync(from, to);
  console.log(`Copied ${from} to ${to}`);
}
